module LFSR (
    output reg [3:0] out,
    input clk,
    input rst
);

reg [3:0] out_reg;
wire feedback;

assign feedback = ~(out_reg[3] ^ out_reg[2]);

always @(posedge clk or posedge rst) begin

    if(rst) begin

        out_reg <= 4'b0000;
    end else begin

        out_reg <= {out_reg[2:0], feedback};
    end
end

assign out = out_reg;
endmodule
